CREATE OR REPLACE FUNCTION public.admin_attendance_break_decision_save(p_store_id bigint, p_employee_id bigint, p_in_event_id bigint, p_break_provided boolean, p_compensate_30m boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_email text;
begin
 if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 if not exists(select 1 from public.employees e where e.id=p_employee_id and e.store_id=p_store_id) then raise exception 'EMPLOYEE_STORE_MISMATCH'; end if;
 if not exists(select 1 from public.attendance_events a where a.id=p_in_event_id and a.employee_id=p_employee_id and a.event_type='IN') then raise exception 'IN_EVENT_NOT_FOUND'; end if;
 v_email:=coalesce(auth.jwt()->>'email','admin');
 insert into public.attendance_break_decisions(store_id,employee_id,in_event_id,break_provided,compensate_30m,updated_by,updated_at)
 values(p_store_id,p_employee_id,p_in_event_id,p_break_provided,case when p_break_provided=false then p_compensate_30m else false end,v_email,now())
 on conflict(in_event_id) do update set break_provided=excluded.break_provided,compensate_30m=excluded.compensate_30m,updated_by=excluded.updated_by,updated_at=now();
 return jsonb_build_object('ok',true);
end$function$

CREATE OR REPLACE FUNCTION public.admin_close_payroll(p_ym text, p_rows json, p_fingerprint text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_actor text; r json; n int:=0; v_month date;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 if p_ym !~ '^\\d{4}-\\d{2}$' then raise exception 'BAD_YM'; end if;
 v_month:=(p_ym||'-01')::date;
 if v_month>=date_trunc('month',now() at time zone 'Asia/Seoul')::date then raise exception 'CURRENT_OR_FUTURE_MONTH_CANNOT_CLOSE'; end if;
 if exists(select 1 from public.payroll_period where ym=p_ym and status='CLOSED') then raise exception 'PAYROLL_ALREADY_CLOSED'; end if;
 v_actor:=coalesce(auth.jwt()->>'email','admin');
 delete from public.payroll_snapshot where ym=p_ym;
 for r in select * from json_array_elements(p_rows) loop
   insert into public.payroll_snapshot(ym,employee_id,employee_name,hours,wage,weeks,base_pay,juhyu_pay,adjust,gross_pay,tax_rate,net_pay,memo,source_fingerprint,closed_by)
   values(p_ym,(r->>'employee_id')::bigint,r->>'employee_name',nullif(r->>'hours','')::numeric,nullif(r->>'wage','')::int,nullif(r->>'weeks','')::int,
   nullif(r->>'base_pay','')::int,nullif(r->>'juhyu_pay','')::int,coalesce(nullif(r->>'adjust','')::int,0),nullif(r->>'gross_pay','')::int,
   nullif(r->>'tax_rate','')::numeric,nullif(r->>'net_pay','')::int,r->>'memo',p_fingerprint,v_actor);
   n:=n+1;
 end loop;
 insert into public.payroll_period(ym,status,updated_by,updated_at) values(p_ym,'CLOSED',v_actor,now())
 on conflict(ym) do update set status='CLOSED',updated_by=v_actor,updated_at=now();
 return json_build_object('ok',true,'count',n);
end $function$

CREATE OR REPLACE FUNCTION public.admin_contract_doc_add(p_employee_id bigint, p_contract_id bigint, p_storage_path text, p_filename text, p_content_type text, p_byte_size integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_actor text;
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  v_actor := coalesce(auth.jwt()->>'email','admin');
  if not exists (
    select 1 from public.employment_contracts c
    join public.employment_periods p on p.id=c.employment_period_id
    where c.id=p_contract_id and p.employee_id=p_employee_id
  ) then
    return json_build_object('ok',false,'error','CONTRACT_NOT_FOUND');
  end if;
  if p_storage_path is null
     or split_part(p_storage_path,'/',1) <> p_employee_id::text
     or length(split_part(p_storage_path,'/',2)) = 0
     or split_part(p_storage_path,'/',3) <> ''
     or (length(p_storage_path) - length(replace(p_storage_path,'/',''))) <> 1
  then return json_build_object('ok',false,'error','PATH_INVALID'); end if;
  if p_filename is null or length(trim(p_filename))=0 then return json_build_object('ok',false,'error','FILENAME_REQUIRED'); end if;
  if p_content_type not in ('application/pdf','image/jpeg','image/png') then return json_build_object('ok',false,'error','UNSUPPORTED_TYPE'); end if;
  if p_byte_size is null or p_byte_size <= 0 or p_byte_size > 10485760 then return json_build_object('ok',false,'error','SIZE_INVALID'); end if;
  insert into public.employee_documents(employee_id,contract_id,storage_path,filename,content_type,byte_size,uploaded_by_email)
  values(p_employee_id,p_contract_id,p_storage_path,p_filename,p_content_type,p_byte_size,v_actor)
  returning id into v_id;
  return json_build_object('ok',true,'id',v_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_contract_doc_list(p_employee_id bigint, p_contract_id bigint)
 RETURNS TABLE(id bigint, filename text, content_type text, byte_size integer, storage_path text, uploaded_by_email text, uploaded_at timestamp with time zone, contract_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  if not exists (
    select 1
    from public.employment_contracts c
    join public.employment_periods p on p.id=c.employment_period_id
    where c.id=p_contract_id and p.employee_id=p_employee_id
  ) then
    raise exception 'CONTRACT_NOT_FOUND';
  end if;
  return query
    select d.id,d.filename,d.content_type,d.byte_size,d.storage_path,d.uploaded_by_email,d.uploaded_at,d.contract_id
    from public.employee_documents d
    where d.employee_id=p_employee_id and d.contract_id=p_contract_id
    order by d.uploaded_at desc;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_contract_night_end_set(p_contract_id bigint, p_night_allowance_end time without time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare actor text; v_id bigint;
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  if p_night_allowance_end is null then return jsonb_build_object('ok',false,'error','BAD_NIGHT_END'); end if;
  actor:=coalesce(auth.jwt()->>'email','admin');
  update public.employment_contracts set night_allowance_end=p_night_allowance_end,updated_by_email=actor,updated_at=now() where id=p_contract_id returning id into v_id;
  if v_id is null then return jsonb_build_object('ok',false,'error','CONTRACT_NOT_FOUND'); end if;
  return jsonb_build_object('ok',true,'id',v_id);
end; $function$

CREATE OR REPLACE FUNCTION public.admin_correct_event(p_action text, p_event_id bigint, p_employee_id bigint, p_new_at timestamp without time zone, p_new_type text, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_actor text; v_new_utc timestamp; v_target bigint;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 v_actor:=coalesce(auth.jwt()->>'email','admin');
 if p_action='VOID_ADD' then
   if p_event_id is null then raise exception 'CORRECTION_ID_REQUIRED'; end if;
   select id into v_target from event_corrections where id=p_event_id and employee_id=p_employee_id and action='ADD';
   if v_target is null then raise exception 'ADD_CORRECTION_NOT_FOUND'; end if;
   insert into event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
   values(null,p_employee_id,'VOID_ADD',null,null,p_reason,v_actor) returning id into v_id;
   update event_corrections set reason=coalesce(reason,'')||' [VOID_ADD:'||v_id||']' where id=v_target;
   return v_id;
 end if;
 if p_action='VOID' and p_event_id is null then raise exception 'EVENT_ID_REQUIRED'; end if;
 v_new_utc:=case when p_new_at is null then null else (p_new_at at time zone 'Asia/Seoul') at time zone 'UTC' end;
 insert into event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
 values(p_event_id,p_employee_id,p_action,v_new_utc,p_new_type,p_reason,v_actor) returning id into v_id;
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_create_employee(p_name text, p_pin text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_id bigint;
  v_store_id bigint;
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  select id into v_store_id
  from public.stores
  where is_active=true
  order by case when id=1 then 0 else 1 end,id
  limit 1;
  if v_store_id is null then raise exception 'STORE_NOT_FOUND'; end if;
  insert into public.employees(name,pin_bcrypt,is_active,store_id)
  values(trim(p_name),crypt(p_pin,gen_salt('bf')),true,v_store_id)
  returning id into v_id;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_create_employee_for_store(p_name text, p_pin text, p_store_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_id bigint;
begin
  if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'NAME_REQUIRED'; end if;
  if p_pin !~ '^\d{4}$' then raise exception 'PIN_REQUIRED'; end if;
  if not exists(select 1 from public.stores where id=p_store_id and is_active=true) then raise exception 'STORE_NOT_FOUND'; end if;
  insert into public.employees(name,pin_bcrypt,is_active,store_id)
  values(trim(p_name),crypt(p_pin,gen_salt('bf')),true,p_store_id)
  returning id into v_id;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_create_employee_onboarding(p_name text, p_pin text, p_started_on date, p_payroll_type text, p_hourly_wage integer, p_monthly_salary integer, p_tax_treatment text, p_business_deduction_rate numeric, p_night_allowance_enabled boolean, p_night_allowance_mode text, p_night_allowance_value numeric, p_night_allowance_start time without time zone, p_memo text, p_workdays jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_emp bigint;
  v_period jsonb;
  v_contract jsonb;
  v_period_id bigint;
  v_contract_id bigint;
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'NAME_REQUIRED'; end if;
  if p_pin !~ '^\d{4}$' then raise exception 'PIN_REQUIRED'; end if;
  if p_started_on is null then raise exception 'START_DATE_REQUIRED'; end if;

  v_emp := public.admin_create_employee(trim(p_name),p_pin);

  v_period := public.admin_employment_period_set(
    null,v_emp,p_started_on,null,null
  );
  if coalesce((v_period->>'ok')::boolean,false) is not true then
    raise exception '%',coalesce(v_period->>'error','PERIOD_SAVE_FAILED');
  end if;
  v_period_id := (v_period->>'id')::bigint;

  v_contract := public.admin_employment_contract_set(
    null,v_period_id,p_started_on,null,p_payroll_type,p_hourly_wage,p_monthly_salary,
    p_tax_treatment,p_business_deduction_rate,coalesce(p_night_allowance_enabled,false),
    p_night_allowance_mode,p_night_allowance_value,coalesce(p_night_allowance_start,time '22:00'),
    p_memo,coalesce(p_workdays,'[]'::jsonb)
  );
  if coalesce((v_contract->>'ok')::boolean,false) is not true then
    raise exception '%',coalesce(v_contract->>'error','CONTRACT_SAVE_FAILED');
  end if;
  v_contract_id := (v_contract->>'id')::bigint;

  update public.employees
  set wage=case when p_payroll_type='HOURLY' then p_hourly_wage else null end,
      tax_rate=case when p_tax_treatment='BUSINESS_INCOME' then p_business_deduction_rate else tax_rate end,
      memo=nullif(p_memo,'')
  where id=v_emp;

  return jsonb_build_object('ok',true,'employee_id',v_emp,'period_id',v_period_id,'contract_id',v_contract_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_create_employee_onboarding_for_store(p_name text, p_pin text, p_started_on date, p_payroll_type text, p_hourly_wage integer, p_monthly_salary integer, p_tax_treatment text, p_business_deduction_rate numeric, p_night_allowance_enabled boolean, p_night_allowance_mode text, p_night_allowance_value numeric, p_night_allowance_start time without time zone, p_memo text, p_workdays jsonb, p_store_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_emp bigint;v_employee_no integer;v_period jsonb;v_contract jsonb;v_period_id bigint;v_contract_id bigint;
begin
  if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'NAME_REQUIRED'; end if;
  if p_pin !~ '^\d{4}$' then raise exception 'PIN_REQUIRED'; end if;
  if p_started_on is null then raise exception 'START_DATE_REQUIRED'; end if;
  if not exists(select 1 from public.stores where id=p_store_id and is_active=true) then raise exception 'STORE_NOT_FOUND'; end if;
  v_emp:=public.admin_create_employee_for_store(trim(p_name),p_pin,p_store_id);
  select employee_no into v_employee_no from public.employees where id=v_emp;
  v_period:=public.admin_employment_period_set(null,v_emp,p_started_on,null,null);
  if coalesce((v_period->>'ok')::boolean,false) is not true then raise exception '%',coalesce(v_period->>'error','PERIOD_SAVE_FAILED'); end if;
  v_period_id:=(v_period->>'id')::bigint;
  v_contract:=public.admin_employment_contract_set(
    null,v_period_id,p_started_on,null,p_payroll_type,p_hourly_wage,p_monthly_salary,p_tax_treatment,
    p_business_deduction_rate,coalesce(p_night_allowance_enabled,false),p_night_allowance_mode,
    p_night_allowance_value,coalesce(p_night_allowance_start,time '22:00'),p_memo,coalesce(p_workdays,'[]'::jsonb)
  );
  if coalesce((v_contract->>'ok')::boolean,false) is not true then raise exception '%',coalesce(v_contract->>'error','CONTRACT_SAVE_FAILED'); end if;
  v_contract_id:=(v_contract->>'id')::bigint;
  update public.employees set
    wage=case when p_payroll_type='HOURLY' then p_hourly_wage else null end,
    tax_rate=case when p_tax_treatment='BUSINESS_INCOME' then p_business_deduction_rate else tax_rate end,
    memo=nullif(p_memo,'') where id=v_emp;
  return jsonb_build_object('ok',true,'employee_id',v_emp,'employee_no',v_employee_no,'period_id',v_period_id,'contract_id',v_contract_id,'store_id',p_store_id);
end
$function$

CREATE OR REPLACE FUNCTION public.admin_doc_add(p_employee_id bigint, p_storage_path text, p_filename text, p_content_type text, p_byte_size integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_actor text;
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  v_actor := coalesce(auth.jwt()->>'email','admin');
  if not exists (select 1 from public.employees e where e.id = p_employee_id) then
    return json_build_object('ok',false,'error','EMPLOYEE_NOT_FOUND');
  end if;
  -- canonical path 검증: "{employee_id}/{object_name}" 정확히 2 segment.
  if p_storage_path is null
     or split_part(p_storage_path,'/',1) <> p_employee_id::text
     or length(split_part(p_storage_path,'/',2)) = 0
     or split_part(p_storage_path,'/',3) <> ''
     or (length(p_storage_path) - length(replace(p_storage_path,'/',''))) <> 1
  then
    return json_build_object('ok',false,'error','PATH_INVALID');
  end if;
  if p_filename is null or length(trim(p_filename))=0 then
    return json_build_object('ok',false,'error','FILENAME_REQUIRED');
  end if;
  if p_content_type not in ('application/pdf','image/jpeg','image/png') then
    return json_build_object('ok',false,'error','UNSUPPORTED_TYPE');
  end if;
  if p_byte_size is null or p_byte_size <= 0 or p_byte_size > 10485760 then
    return json_build_object('ok',false,'error','SIZE_INVALID');
  end if;
  insert into public.employee_documents(employee_id,storage_path,filename,content_type,byte_size,uploaded_by_email)
    values (p_employee_id,p_storage_path,p_filename,p_content_type,p_byte_size,v_actor)
    returning id into v_id;
  return json_build_object('ok',true,'id',v_id);
end; $function$

CREATE OR REPLACE FUNCTION public.admin_doc_delete(p_document_id bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.employee_documents%rowtype;
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  select * into v_row from public.employee_documents where id=p_document_id;
  if not found then return json_build_object('ok',false,'error','DOC_NOT_FOUND'); end if;
  delete from public.employee_documents where id=p_document_id;
  return json_build_object('ok',true,'storage_path',v_row.storage_path);
end; $function$

CREATE OR REPLACE FUNCTION public.admin_employment_period_contract_create(p_employee_id bigint, p_started_on date, p_ended_on date, p_period_note text, p_effective_from date, p_effective_to date, p_payroll_type text, p_hourly_wage integer, p_monthly_salary integer, p_tax_treatment text, p_business_deduction_rate numeric, p_night_allowance_enabled boolean, p_night_allowance_mode text, p_night_allowance_value numeric, p_night_allowance_start time without time zone, p_contract_memo text, p_workdays jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_period jsonb;
  v_contract jsonb;
  v_msg text;
begin
  if not public.is_admin() then
    raise exception 'NOT_AUTHORIZED';
  end if;

  begin
    v_period := public.admin_employment_period_set(
      null, p_employee_id, p_started_on, p_ended_on, p_period_note
    );
    if not coalesce((v_period->>'ok')::boolean,false) then
      raise exception 'ATOMIC_PERIOD:%', coalesce(v_period->>'error','SAVE_FAILED');
    end if;

    v_contract := public.admin_employment_contract_set(
      null,
      (v_period->>'id')::bigint,
      p_effective_from,
      p_effective_to,
      p_payroll_type,
      p_hourly_wage,
      p_monthly_salary,
      p_tax_treatment,
      p_business_deduction_rate,
      p_night_allowance_enabled,
      p_night_allowance_mode,
      p_night_allowance_value,
      p_night_allowance_start,
      p_contract_memo,
      p_workdays
    );
    if not coalesce((v_contract->>'ok')::boolean,false) then
      raise exception 'ATOMIC_CONTRACT:%', coalesce(v_contract->>'error','SAVE_FAILED');
    end if;

    return jsonb_build_object(
      'ok',true,
      'period_id',(v_period->>'id')::bigint,
      'contract_id',(v_contract->>'id')::bigint,
      'weekly_contracted_minutes',v_contract->'weekly_contracted_minutes'
    );
  exception when raise_exception then
    v_msg := sqlerrm;
    if v_msg like 'ATOMIC_PERIOD:%' then
      return jsonb_build_object('ok',false,'error',substring(v_msg from 15));
    elsif v_msg like 'ATOMIC_CONTRACT:%' then
      return jsonb_build_object('ok',false,'error',substring(v_msg from 17));
    end if;
    raise;
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_grant(p_email text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid; v_cnt int; v_norm text;
begin
  if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  perform pg_advisory_xact_lock(hashtext('admin_users_mutation'));
  v_norm := lower(trim(p_email));
  select count(*) into v_cnt from auth.users where lower(trim(email))=v_norm;
  if v_cnt = 0 then return json_build_object('ok',false,'error','AUTH_USER_NOT_FOUND'); end if;
  if v_cnt > 1 then return json_build_object('ok',false,'error','AUTH_USER_AMBIGUOUS'); end if;
  select id into v_uid from auth.users where lower(trim(email))=v_norm;
  -- 이미 관리자면 명시적으로 알림 (앱 결과 정확성)
  if exists (select 1 from public.admin_users where user_id=v_uid) then
    return json_build_object('ok',false,'error','ALREADY_ADMIN','user_id',v_uid);
  end if;
  insert into public.admin_users(user_id,email,note)
    values (v_uid, v_norm, 'granted by '||coalesce(auth.jwt()->>'email','admin'));
  return json_build_object('ok',true,'user_id',v_uid);
end; $function$

CREATE OR REPLACE FUNCTION public.admin_hq_product_apply(p_product_id bigint, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  p public.hq_products%rowtype;
  v_comp jsonb;
  v_item_id bigint;
  v_recipe_id bigint;
  v_created boolean;
  v_store_count integer:=0;
  v_action text:=upper(trim(coalesce(p_action,'')));
  v_alias text;
  v_old_hq_items bigint[]:='{}';
begin
  if not public.is_hq_admin() and session_user not in ('postgres','supabase_admin') then raise exception 'NOT_AUTHORIZED'; end if;
  if v_action not in ('LAUNCH','DISCONTINUE') then raise exception 'INVALID_ACTION'; end if;
  select * into p from public.hq_products where id=p_product_id for update;
  if p.id is null then raise exception 'PRODUCT_NOT_FOUND'; end if;

  if v_action='LAUNCH' then
    select coalesce(array_agg(item_id),'{}') into v_old_hq_items
      from public.hq_product_items where product_id=p.id and created_by_hq;
    delete from public.hq_product_items where product_id=p.id;
    for v_comp in select * from jsonb_array_elements(p.component_blueprint) loop
      v_item_id:=nullif(v_comp->>'item_id','')::bigint;
      v_created:=coalesce(v_item_id=any(v_old_hq_items),false);
      if v_item_id is not null then
        update public.inventory_items set is_active=true,updated_at=now() where id=v_item_id returning id into v_item_id;
        if v_item_id is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
      else
        select i.id into v_item_id from public.inventory_items i where lower(i.sku)=lower(trim(v_comp->>'sku')) limit 1;
        if v_item_id is null then
          insert into public.inventory_items(sku,name,unit,is_active,reorder_level,pack_quantity,pack_unit,is_demo)
          values(trim(v_comp->>'sku'),trim(v_comp->>'name'),trim(v_comp->>'unit'),true,
            nullif(v_comp->>'reorder_level','')::numeric,nullif(v_comp->>'pack_quantity','')::numeric,
            nullif(trim(coalesce(v_comp->>'pack_unit','')),''),false)
          returning id into v_item_id;
          v_created:=true;
        else
          v_created:=coalesce(v_item_id=any(v_old_hq_items),false);
          update public.inventory_items set name=trim(v_comp->>'name'),unit=trim(v_comp->>'unit'),is_active=true,
            reorder_level=coalesce(nullif(v_comp->>'reorder_level','')::numeric,reorder_level),
            pack_quantity=coalesce(nullif(v_comp->>'pack_quantity','')::numeric,pack_quantity),
            pack_unit=coalesce(nullif(trim(coalesce(v_comp->>'pack_unit','')),''),pack_unit),updated_at=now()
          where id=v_item_id;
        end if;
      end if;
      insert into public.hq_product_items(product_id,item_id,quantity,created_by_hq)
      values(p.id,v_item_id,(v_comp->>'quantity')::numeric,v_created)
      on conflict(product_id,item_id) do update set quantity=excluded.quantity,
        created_by_hq=public.hq_product_items.created_by_hq or excluded.created_by_hq;
    end loop;

    if p.recipe_version_id is not null then
      update public.recipe_versions set effective_to=current_date where id=p.recipe_version_id and effective_to is null;
    end if;
    insert into public.recipe_versions(menu_key,menu_name,category,effective_from,effective_to,is_demo)
    values(p.product_key,p.name,p.category,current_date,null,false) returning id into v_recipe_id;
    insert into public.recipe_components(recipe_version_id,item_id,quantity)
      select v_recipe_id,item_id,quantity from public.hq_product_items where product_id=p.id;

    insert into public.store_product_assignments(product_id,store_id,status,applied_at,discontinued_at)
      select p.id,s.id,'ACTIVE',now(),null from public.stores s where s.is_active
      on conflict(product_id,store_id) do update set status='ACTIVE',applied_at=now(),discontinued_at=null;
    get diagnostics v_store_count=row_count;

    delete from public.hq_product_transaction_links where product_id=p.id;
    foreach v_alias in array p.sale_aliases loop
      insert into public.hq_product_transaction_links values(p.id,'SALE',v_alias) on conflict do nothing;
    end loop;
    foreach v_alias in array p.purchase_aliases loop
      insert into public.hq_product_transaction_links values(p.id,'PURCHASE',v_alias) on conflict do nothing;
    end loop;
    update public.hq_products set status='ACTIVE',effective_from=current_date,effective_to=null,
      scheduled_at=null,recipe_version_id=v_recipe_id,updated_at=now() where id=p.id;
  else
    if p.recipe_version_id is not null then
      update public.recipe_versions set effective_to=current_date where id=p.recipe_version_id and effective_to is null;
    end if;
    update public.store_product_assignments set status='DISCONTINUED',discontinued_at=now()
      where product_id=p.id and status='ACTIVE';
    get diagnostics v_store_count=row_count;
    update public.inventory_items i set is_active=false,updated_at=now()
      where exists(select 1 from public.hq_product_items pi where pi.product_id=p.id and pi.item_id=i.id and pi.created_by_hq)
        and not exists(select 1 from public.hq_product_items pi2 join public.hq_products p2 on p2.id=pi2.product_id
          where pi2.item_id=i.id and p2.id<>p.id and p2.status='ACTIVE');
    update public.hq_products set status='DISCONTINUED',effective_to=current_date,
      scheduled_at=null,updated_at=now() where id=p.id;
    v_recipe_id:=p.recipe_version_id;
  end if;

  insert into public.hq_product_rollouts(product_id,action,affected_store_count,recipe_version_id,details,actor_id)
  values(p.id,v_action,v_store_count,v_recipe_id,
    jsonb_build_object('product_key',p.product_key,'name',p.name,'component_count',jsonb_array_length(p.component_blueprint)),auth.uid());
  return jsonb_build_object('ok',true,'action',v_action,'product_id',p.id,'affected_store_count',v_store_count,'recipe_version_id',v_recipe_id);
end
$function$

CREATE OR REPLACE FUNCTION public.admin_hq_product_removal_schedule(p_product_ids bigint[], p_removal_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_at timestamptz;
  v_requested integer;
  v_updated integer;
begin
  if not public.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  v_requested:=coalesce(array_length(p_product_ids,1),0);
  if v_requested=0 then raise exception 'PRODUCT_REQUIRED'; end if;
  if p_removal_date is null or p_removal_date <= (now() at time zone 'Asia/Seoul')::date then
    raise exception 'FUTURE_DATE_REQUIRED';
  end if;
  if exists(
    select 1 from unnest(p_product_ids) requested(id)
    left join public.hq_products p on p.id=requested.id
    where p.id is null or p.status<>'ACTIVE'
  ) then
    raise exception 'PRODUCT_NOT_REMOVABLE';
  end if;
  v_at:=p_removal_date::timestamp at time zone 'Asia/Seoul';
  update public.hq_products
    set removal_scheduled_at=v_at,updated_at=now()
    where id=any(p_product_ids) and status='ACTIVE';
  get diagnostics v_updated=row_count;
  if v_updated<>v_requested then raise exception 'PRODUCT_SELECTION_MISMATCH'; end if;
  return jsonb_build_object('ok',true,'scheduled_count',v_updated,'removal_scheduled_at',v_at);
end
$function$

CREATE OR REPLACE FUNCTION public.admin_hq_product_save(p_product_id bigint, p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id bigint;
  v_key text;
  v_name text;
  v_category text;
  v_components jsonb;
  v_comp jsonb;
begin
  if not public.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  v_name:=trim(coalesce(p_payload->>'name',''));
  v_key:=upper(regexp_replace(trim(coalesce(p_payload->>'product_key','')),'[^A-Za-z0-9_-]+','-','g'));
  v_category:=nullif(trim(coalesce(p_payload->>'category','')),'');
  v_components:=coalesce(p_payload->'components','[]'::jsonb);
  if v_name='' then raise exception 'PRODUCT_NAME_REQUIRED'; end if;
  if v_key='' then raise exception 'PRODUCT_KEY_REQUIRED'; end if;
  if jsonb_typeof(v_components)<>'array' or jsonb_array_length(v_components)=0 then raise exception 'COMPONENT_REQUIRED'; end if;
  for v_comp in select * from jsonb_array_elements(v_components) loop
    if coalesce((v_comp->>'quantity')::numeric,0)<=0 then raise exception 'INVALID_COMPONENT_QUANTITY'; end if;
    if nullif(v_comp->>'item_id','') is null and
       (trim(coalesce(v_comp->>'sku',''))='' or trim(coalesce(v_comp->>'name',''))='' or trim(coalesce(v_comp->>'unit',''))='')
    then raise exception 'NEW_ITEM_FIELDS_REQUIRED'; end if;
  end loop;
  if p_product_id is null then
    insert into public.hq_products(product_key,name,category,sale_aliases,purchase_aliases,component_blueprint,created_by)
    values(v_key,v_name,v_category,
      array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'sale_aliases','[]'::jsonb)) x where trim(x)<>''),
      array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'purchase_aliases','[]'::jsonb)) x where trim(x)<>''),
      v_components,auth.uid()) returning id into v_id;
  else
    update public.hq_products set product_key=v_key,name=v_name,category=v_category,
      sale_aliases=array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'sale_aliases','[]'::jsonb)) x where trim(x)<>''),
      purchase_aliases=array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'purchase_aliases','[]'::jsonb)) x where trim(x)<>''),
      component_blueprint=v_components,updated_at=now()
    where id=p_product_id returning id into v_id;
    if v_id is null then raise exception 'PRODUCT_NOT_FOUND'; end if;
  end if;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_hq_product_schedule(p_product_id bigint, p_launch_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_at timestamptz;
  v_status text;
  v_pending boolean;
begin
  if not public.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;

  select status,has_pending_changes into v_status,v_pending
  from public.hq_products where id=p_product_id for update;
  if v_status is null then raise exception 'PRODUCT_NOT_FOUND'; end if;

  if p_launch_date is null then
    if v_status='SCHEDULED' then
      update public.hq_products
        set status='DRAFT',scheduled_at=null,updated_at=now()
        where id=p_product_id;
      return jsonb_build_object('ok',true,'status','DRAFT','scheduled_at',null,'schedule_type','LAUNCH');
    elsif v_status='ACTIVE' and exists(select 1 from public.hq_products where id=p_product_id and scheduled_at is not null) then
      update public.hq_products set scheduled_at=null,updated_at=now() where id=p_product_id;
      return jsonb_build_object('ok',true,'status','ACTIVE','scheduled_at',null,'schedule_type','UPDATE');
    end if;
    raise exception 'PRODUCT_NOT_SCHEDULED';
  end if;

  if p_launch_date <= (now() at time zone 'Asia/Seoul')::date then
    raise exception 'FUTURE_DATE_REQUIRED';
  end if;
  v_at:=p_launch_date::timestamp at time zone 'Asia/Seoul';

  if v_status='ACTIVE' then
    if not coalesce(v_pending,false) then raise exception 'PRODUCT_HAS_NO_PENDING_CHANGES'; end if;
    update public.hq_products set scheduled_at=v_at,updated_at=now() where id=p_product_id;
    return jsonb_build_object('ok',true,'status','ACTIVE','scheduled_at',v_at,'schedule_type','UPDATE');
  end if;

  update public.hq_products
    set status='SCHEDULED',scheduled_at=v_at,effective_from=p_launch_date,updated_at=now()
    where id=p_product_id and status in ('DRAFT','SCHEDULED','DISCONTINUED')
    returning status into v_status;
  if v_status is null then raise exception 'PRODUCT_NOT_SCHEDULABLE'; end if;
  return jsonb_build_object('ok',true,'status',v_status,'scheduled_at',v_at,'schedule_type','LAUNCH');
end
$function$

CREATE OR REPLACE FUNCTION public.admin_inventory_manual_save(p_id bigint, p_store_id bigint, p_name text, p_sku text, p_category text, p_unit text, p_on_hand numeric, p_target_level numeric, p_reorder_point numeric, p_thumbnail_url text)
 RETURNS inventory_manual_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.inventory_manual_items;
begin
  if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'name required'; end if;
  if coalesce(p_target_level,0)<0 or coalesce(p_reorder_point,0)<0 or coalesce(p_on_hand,0)<0 then raise exception 'stock values must be >= 0'; end if;
  if coalesce(p_target_level,0)>0 and coalesce(p_reorder_point,0)>coalesce(p_target_level,0) then raise exception 'reorder point must not exceed target level'; end if;
  if p_id is null then
    insert into public.inventory_manual_items(store_id,name,sku,category,unit,on_hand,target_level,reorder_point,thumbnail_url)
    values(coalesce(p_store_id,1),trim(p_name),nullif(trim(p_sku),''),nullif(trim(p_category),''),coalesce(nullif(trim(p_unit),''),'ea'),coalesce(p_on_hand,0),coalesce(p_target_level,0),coalesce(p_reorder_point,0),nullif(trim(p_thumbnail_url),''))
    on conflict(store_id,name) do update set sku=excluded.sku,category=excluded.category,unit=excluded.unit,on_hand=excluded.on_hand,target_level=excluded.target_level,reorder_point=excluded.reorder_point,thumbnail_url=excluded.thumbnail_url,updated_at=now()
    returning * into r;
  else
    update public.inventory_manual_items set name=trim(p_name),sku=nullif(trim(p_sku),''),category=nullif(trim(p_category),''),unit=coalesce(nullif(trim(p_unit),''),'ea'),on_hand=coalesce(p_on_hand,0),target_level=coalesce(p_target_level,0),reorder_point=coalesce(p_reorder_point,0),thumbnail_url=nullif(trim(p_thumbnail_url),''),updated_at=now()
    where id=p_id and store_id=coalesce(p_store_id,1) returning * into r;
  end if;
  return r;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_inventory_manual_save_v2(p_id bigint, p_store_id bigint, p_name text, p_sku text, p_category text, p_unit text, p_on_hand numeric, p_target_level numeric, p_reorder_point numeric, p_thumbnail_url text, p_source_item_id bigint DEFAULT NULL::bigint)
 RETURNS inventory_manual_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.inventory_manual_items; v_source public.inventory_items%rowtype;
begin
  if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if coalesce(p_on_hand,0)<0 or coalesce(p_target_level,0)<0 or coalesce(p_reorder_point,0)<0 then raise exception 'INVALID_STOCK'; end if;
  if coalesce(p_target_level,0)>0 and coalesce(p_reorder_point,0)>coalesce(p_target_level,0) then raise exception 'INVALID_REORDER_POINT'; end if;
  if p_source_item_id is not null then
    select * into v_source from public.inventory_items where id=p_source_item_id and is_active;
    if v_source.id is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
    p_name:=v_source.name; p_sku:=v_source.sku; p_unit:=v_source.unit;
  elsif nullif(trim(p_name),'') is null then
    raise exception 'NAME_REQUIRED';
  end if;
  if p_id is null then
    insert into public.inventory_manual_items(store_id,name,sku,category,unit,on_hand,target_level,reorder_point,thumbnail_url,source_item_id)
    values(p_store_id,trim(p_name),nullif(trim(p_sku),''),nullif(trim(p_category),''),coalesce(nullif(trim(p_unit),''),'ea'),coalesce(p_on_hand,0),coalesce(p_target_level,0),coalesce(p_reorder_point,0),nullif(trim(p_thumbnail_url),''),p_source_item_id)
    on conflict(store_id,name) do update set sku=excluded.sku,category=excluded.category,unit=excluded.unit,on_hand=excluded.on_hand,target_level=excluded.target_level,reorder_point=excluded.reorder_point,thumbnail_url=excluded.thumbnail_url,source_item_id=coalesce(excluded.source_item_id,public.inventory_manual_items.source_item_id),updated_at=now()
    returning * into r;
  else
    update public.inventory_manual_items set name=trim(p_name),sku=nullif(trim(p_sku),''),category=nullif(trim(p_category),''),unit=coalesce(nullif(trim(p_unit),''),'ea'),on_hand=coalesce(p_on_hand,0),target_level=coalesce(p_target_level,0),reorder_point=coalesce(p_reorder_point,0),thumbnail_url=nullif(trim(p_thumbnail_url),''),source_item_id=coalesce(p_source_item_id,source_item_id),updated_at=now()
    where id=p_id and store_id=p_store_id returning * into r;
  end if;
  if r.id is null then raise exception 'INVENTORY_SAVE_FAILED'; end if;
  return r;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_inventory_purchase_order_create(p_store_id bigint, p_item_id bigint, p_manual_item_id bigint, p_quantity numeric, p_note text DEFAULT NULL::text)
 RETURNS inventory_purchase_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.inventory_purchase_orders; v_name text; v_unit text; v_stock text; v_order text; v_conv numeric;
begin
 if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 if coalesce(p_quantity,0)<=0 then raise exception 'INVALID_QUANTITY'; end if;
 if (p_item_id is null)=(p_manual_item_id is null) then raise exception 'EXACTLY_ONE_ITEM_REQUIRED'; end if;
 if p_manual_item_id is not null then
   select name,unit,stock_unit,order_unit,conversion_quantity into v_name,v_unit,v_stock,v_order,v_conv
   from public.inventory_manual_items where id=p_manual_item_id and store_id=p_store_id and is_active;
 else
   select name,unit,stock_unit,order_unit,conversion_quantity into v_name,v_unit,v_stock,v_order,v_conv
   from public.inventory_items where id=p_item_id and is_active;
 end if;
 if v_name is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
 v_stock:=coalesce(nullif(v_stock,''),v_unit);
 v_order:=coalesce(nullif(v_order,''),v_unit);
 v_conv:=coalesce(v_conv,1);
 insert into public.inventory_purchase_orders(store_id,item_id,manual_item_id,item_name,unit,stock_unit,order_unit,conversion_quantity,ordered_quantity,note)
 values(p_store_id,p_item_id,p_manual_item_id,v_name,v_order,v_stock,v_order,v_conv,p_quantity,nullif(trim(p_note),''))
 returning * into r;
 return r;
end $function$

CREATE OR REPLACE FUNCTION public.admin_inventory_purchase_receive(p_order_id bigint, p_quantity numeric)
 RETURNS inventory_purchase_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.inventory_purchase_orders; v_remaining numeric; v_stock_qty numeric; v_updated bigint;
begin
 select * into r from public.inventory_purchase_orders where id=p_order_id for update;
 if r.id is null then raise exception 'ORDER_NOT_FOUND'; end if;
 if not public.can_manage_store(r.store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 if r.status not in ('ORDERED','PARTIAL') then raise exception 'ORDER_NOT_RECEIVABLE'; end if;
 v_remaining:=r.ordered_quantity-r.received_quantity;
 if coalesce(p_quantity,0)<=0 or p_quantity>v_remaining then raise exception 'INVALID_RECEIVE_QUANTITY'; end if;
 v_stock_qty:=p_quantity*coalesce(r.conversion_quantity,1);
 if r.manual_item_id is not null then
   update public.inventory_manual_items set on_hand=on_hand+v_stock_qty,updated_at=now()
   where id=r.manual_item_id and store_id=r.store_id returning id into v_updated;
   if v_updated is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
 else
   if not exists(select 1 from public.inventory_items where id=r.item_id) then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
   insert into public.inventory_movements(item_id,business_date,movement_type,quantity,source_type,source_key,note)
   values(r.item_id,(now() at time zone 'Asia/Seoul')::date,'RECEIPT',v_stock_qty,'PURCHASE_ORDER',r.id::text,
          '발주 입고 '||p_quantity||' '||coalesce(r.order_unit,r.unit)||case when coalesce(r.conversion_quantity,1)<>1 then ' → '||v_stock_qty||' '||coalesce(r.stock_unit,r.unit) else '' end);
 end if;
 update public.inventory_purchase_orders
 set received_quantity=received_quantity+p_quantity,
     status=case when received_quantity+p_quantity>=ordered_quantity then 'RECEIVED' else 'PARTIAL' end,
     received_at=case when received_quantity+p_quantity>=ordered_quantity then now() else received_at end,
     updated_at=now()
 where id=r.id returning * into r;
 return r;
end $function$

CREATE OR REPLACE FUNCTION public.admin_inventory_unit_config_save(p_item_id bigint, p_stock_unit text, p_order_unit text, p_conversion_quantity numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.inventory_items%rowtype;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 if p_item_id is null then raise exception 'ITEM_REQUIRED'; end if;
 if nullif(btrim(p_stock_unit),'') is null or nullif(btrim(p_order_unit),'') is null then raise exception 'UNIT_REQUIRED'; end if;
 if p_conversion_quantity is null or p_conversion_quantity<=0 then raise exception 'INVALID_CONVERSION_QUANTITY'; end if;
 update public.inventory_items
 set stock_unit=btrim(p_stock_unit),order_unit=btrim(p_order_unit),conversion_quantity=p_conversion_quantity,
     pack_unit=btrim(p_order_unit),pack_quantity=p_conversion_quantity
 where id=p_item_id returning * into r;
 if not found then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
 return jsonb_build_object('ok',true,'id',r.id,'stock_unit',r.stock_unit,'order_unit',r.order_unit,'conversion_quantity',r.conversion_quantity);
end $function$

CREATE OR REPLACE FUNCTION public.admin_operations_collect_request(p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare bid bigint;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 insert into operations_import_batches(source,source_store_key,idempotency_key,file_name,status,row_count)
 values(trim(p_source),'default',md5(trim(p_source)||clock_timestamp()::text),null,'READY',0) returning id into bid;
 return jsonb_build_object('ok',true,'batch_id',bid,'status','READY','source',trim(p_source));
end $function$

CREATE OR REPLACE FUNCTION public.admin_operations_import_stage(p_source text, p_file_name text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare bid bigint; r jsonb; n int:=0; sk text; bdate date;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 if coalesce(jsonb_typeof(p_rows),'')<>'array' then raise exception 'ROWS_MUST_BE_ARRAY'; end if;
 insert into operations_import_batches(source,source_store_key,idempotency_key,file_name,status,row_count,started_at)
 values(trim(p_source),'store-'||coalesce(nullif(current_setting('request.headers',true)::jsonb->>'x-store-id',''),'default'),md5(coalesce(p_file_name,'')||clock_timestamp()::text),p_file_name,'PROCESSING',jsonb_array_length(p_rows),now()) returning id into bid;
 for r in select * from jsonb_array_elements(p_rows) loop
   n:=n+1; sk:=coalesce(nullif(r->>'source_record_key',''),bid::text||'-'||n);
   begin bdate:=nullif(r->>'business_date','')::date; exception when others then bdate:=null; end;
   insert into operations_raw_records(batch_id,source,source_store_key,source_record_key,business_date,payload,payload_hash)
   values(bid,trim(p_source),'default',sk,bdate,r,md5(r::text))
   on conflict(source,source_store_key,source_record_key) do update set payload=excluded.payload,payload_hash=excluded.payload_hash,business_date=excluded.business_date,ingested_at=now();
 end loop;
 update operations_import_batches set status='COMPLETED',completed_at=now() where id=bid;
 return jsonb_build_object('ok',true,'batch_id',bid,'row_count',n);
exception when others then
 if bid is not null then update operations_import_batches set status='FAILED',error_message=sqlerrm,completed_at=now() where id=bid; end if;
 raise;
end $function$

CREATE OR REPLACE FUNCTION public.admin_operations_summary(p_from date, p_to date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sales bigint; v_purchases bigint; v_refunds bigint; v_tx bigint; v_items bigint; v_imports bigint;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 if p_from is null or p_to is null or p_to < p_from then raise exception 'INVALID_RANGE'; end if;
 select coalesce(sum(case when transaction_type='SALE' and status='CONFIRMED' then total_amount else 0 end),0),
        coalesce(sum(case when transaction_type='PURCHASE' and status='CONFIRMED' then total_amount else 0 end),0),
        coalesce(sum(case when transaction_type='REFUND' and status='CONFIRMED' then total_amount else 0 end),0),
        count(*) into v_sales,v_purchases,v_refunds,v_tx
 from public.operations_transactions where business_date between p_from and p_to;
 select count(*) into v_items from public.inventory_items where is_active;
 select count(*) into v_imports from public.operations_import_batches where created_at::date between p_from and p_to;
 return json_build_object('sales',v_sales,'purchases',v_purchases,'refunds',v_refunds,'transaction_count',v_tx,'active_items',v_items,'import_count',v_imports);
end $function$

CREATE OR REPLACE FUNCTION public.admin_operations_trend(p_window text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_start timestamptz; v_bucket text; v json;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 case p_window
 when '1h' then v_start=now()-interval '1 hour'; v_bucket='minute';
 when '24h' then v_start=now()-interval '24 hours'; v_bucket='hour';
 when '7d' then v_start=now()-interval '7 days'; v_bucket='day';
 when '1m' then v_start=now()-interval '1 month'; v_bucket='day';
 when '6m' then v_start=now()-interval '6 months'; v_bucket='week';
 when '1y' then v_start=now()-interval '1 year'; v_bucket='month';
 else raise exception 'INVALID_WINDOW';
 end case;
 with base as(
  select date_trunc(v_bucket,transacted_at) bucket,transaction_type,coalesce(counterparty,'미분류') menu,total_amount
  from public.operations_transactions where transacted_at>=v_start and status='CONFIRMED'
 ), totals as(
  select bucket,sum(case when transaction_type='SALE' then total_amount when transaction_type='REFUND' then -total_amount else 0 end) sales,
  sum(case when transaction_type='PURCHASE' then total_amount else 0 end) purchases from base group by bucket
 ), menus as(
  select bucket,menu,sum(case when transaction_type='SALE' then total_amount when transaction_type='REFUND' then -total_amount else 0 end) amount
  from base where transaction_type in('SALE','REFUND') group by bucket,menu
 ), topmenus as(select menu,sum(amount) amount from menus group by menu order by amount desc limit 8)
 select json_build_object(
  'window',p_window,'bucket',v_bucket,
  'totals',coalesce((select json_agg(t order by bucket) from totals t),'[]'::json),
  'menus',coalesce((select json_agg(m order by bucket,menu) from menus m join topmenus tm using(menu)),'[]'::json),
  'menu_names',coalesce((select json_agg(menu order by amount desc) from topmenus),'[]'::json)
 ) into v; return v;
end $function$

CREATE OR REPLACE FUNCTION public.admin_recipe_save(p_recipe_id bigint, p_menu_name text, p_category text, p_components jsonb, p_thumbnail_url text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare rid bigint; comp jsonb; iid bigint; qty numeric;
begin
 if not public.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 if coalesce(trim(p_menu_name),'')='' then raise exception 'MENU_NAME_REQUIRED'; end if;
 if coalesce(jsonb_typeof(p_components),'')<>'array' or jsonb_array_length(p_components)=0 then raise exception 'COMPONENT_REQUIRED'; end if;
 if p_recipe_id is null then
  insert into recipe_versions(menu_key,menu_name,category,effective_from,effective_to,is_demo,thumbnail_url)
  values('ADMIN-'||upper(substr(md5(p_menu_name||clock_timestamp()::text),1,12)),trim(p_menu_name),nullif(trim(p_category),''),current_date,null,false,nullif(trim(p_thumbnail_url),''))
  returning id into rid;
 else
  select id into rid from recipe_versions where id=p_recipe_id and effective_to is null;
  if rid is null then raise exception 'RECIPE_NOT_FOUND'; end if;
  update recipe_versions set menu_name=trim(p_menu_name),category=nullif(trim(p_category),''),thumbnail_url=nullif(trim(p_thumbnail_url),'') where id=rid;
  delete from recipe_components where recipe_version_id=rid;
 end if;
 for comp in select * from jsonb_array_elements(p_components) loop
  iid=(comp->>'item_id')::bigint; qty=(comp->>'quantity')::numeric;
  if qty<=0 or not exists(select 1 from inventory_items where id=iid and is_active=true) then raise exception 'INVALID_COMPONENT'; end if;
  insert into recipe_components(recipe_version_id,item_id,quantity) values(rid,iid,qty);
 end loop;
 return rid;
end $function$

