CREATE OR REPLACE FUNCTION public.admin_store_product_retirement_finalize(p_store_id bigint, p_product_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_positive jsonb; v_untracked jsonb;
begin
  if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if not exists(select 1 from public.store_product_assignments where store_id=p_store_id and product_id=p_product_id and status='RETIRING') then
    raise exception 'RETIREMENT_NOT_PENDING';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('name',i.name,'on_hand',m.on_hand,'unit',m.unit)),'[]'::jsonb)
  into v_positive
  from public.hq_product_items pi
  join public.inventory_items i on i.id=pi.item_id
  join public.inventory_manual_items m on m.store_id=p_store_id and m.source_item_id=i.id and m.is_active
  where pi.product_id=p_product_id and pi.created_by_hq and m.on_hand>0;

  select coalesce(jsonb_agg(jsonb_build_object('item_id',i.id,'name',i.name)),'[]'::jsonb)
  into v_untracked
  from public.hq_product_items pi
  join public.inventory_items i on i.id=pi.item_id
  where pi.product_id=p_product_id and pi.created_by_hq
    and not exists(select 1 from public.inventory_manual_items m where m.store_id=p_store_id and m.source_item_id=i.id and m.is_active);

  if jsonb_array_length(v_positive)>0 then
    return jsonb_build_object('ok',false,'error','STOCK_REMAINS','items',v_positive);
  end if;
  if jsonb_array_length(v_untracked)>0 then
    return jsonb_build_object('ok',false,'error','STOCK_NOT_TRACKED','items',v_untracked);
  end if;

  update public.store_product_assignments set status='DISCONTINUED',discontinued_at=now(),retirement_completed_at=now()
  where store_id=p_store_id and product_id=p_product_id and status='RETIRING';

  update public.inventory_items i set is_active=false,updated_at=now()
  where exists(select 1 from public.hq_product_items pi where pi.product_id=p_product_id and pi.item_id=i.id and pi.created_by_hq)
    and not exists(
      select 1 from public.hq_product_items pi2 join public.hq_products p2 on p2.id=pi2.product_id
      where pi2.item_id=i.id and p2.id<>p_product_id and p2.status='ACTIVE'
    )
    and not exists(
      select 1 from public.store_product_assignments a
      join public.hq_product_items pi3 on pi3.product_id=a.product_id and pi3.item_id=i.id
      where a.status in ('ACTIVE','RETIRING')
    );
  return jsonb_build_object('ok',true,'status','DISCONTINUED');
end
$function$

CREATE OR REPLACE FUNCTION public.admin_store_recipe_override_save(p_store_id bigint, p_menu_key text, p_menu_name text, p_category text, p_components jsonb, p_thumbnail_url text, p_instructions jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_comp jsonb; v_item public.inventory_items%rowtype; v_normalized jsonb='[]'::jsonb;
begin
  if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if not exists(
    select 1 from public.hq_products p join public.store_product_assignments a on a.product_id=p.id
    where p.product_key=p_menu_key and a.store_id=p_store_id and a.status in ('ACTIVE','RETIRING')
  ) then raise exception 'RECIPE_NOT_FOUND'; end if;
  if jsonb_typeof(p_components)<>'array' or jsonb_array_length(p_components)=0 then
    raise exception 'COMPONENT_REQUIRED';
  end if;
  for v_comp in select * from jsonb_array_elements(p_components) loop
    select * into v_item from public.inventory_items
    where id=nullif(v_comp->>'item_id','')::bigint and is_active;
    if v_item.id is null or coalesce((v_comp->>'quantity')::numeric,0)<=0 then
      raise exception 'INVALID_COMPONENT';
    end if;
    v_normalized:=v_normalized||jsonb_build_array(jsonb_build_object(
      'item_id',v_item.id,'item_name',v_item.name,'unit',v_item.unit,
      'quantity',(v_comp->>'quantity')::numeric
    ));
  end loop;
  if p_instructions is not null and jsonb_typeof(p_instructions)<>'array' then
    raise exception 'INVALID_INSTRUCTIONS';
  end if;
  insert into public.store_recipe_overrides(
    store_id,menu_key,menu_name,category,thumbnail_url,instructions,components,updated_by,updated_at
  ) values(
    p_store_id,p_menu_key,nullif(trim(p_menu_name),''),nullif(trim(p_category),''),
    nullif(trim(p_thumbnail_url),''),p_instructions,v_normalized,auth.uid(),now()
  ) on conflict(store_id,menu_key) do update set
    menu_name=excluded.menu_name,category=excluded.category,
    thumbnail_url=excluded.thumbnail_url,instructions=excluded.instructions,components=excluded.components,
    updated_by=auth.uid(),updated_at=now();
  return jsonb_build_object('ok',true,'store_id',p_store_id,'menu_key',p_menu_key);
end
$function$

