CREATE OR REPLACE FUNCTION public.substitution_clock_in(p_request bigint, p_employee bigint, p_pin text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare h text;r public.substitution_requests%rowtype;now_kst timestamp:=clock_timestamp() at time zone 'Asia/Seoul';now_utc timestamp:=clock_timestamp() at time zone 'UTC';last_type text;
begin
 select pin_bcrypt into h from employees where id=p_employee and is_active=true;
 if h is null or crypt(p_pin,h)<>h then return json_build_object('ok',false,'error','BAD_PIN'); end if;
 select * into r from substitution_requests where id=p_request and substitute_employee_id=p_employee for update;
 if not found or r.status<>'ACCEPTED' then return json_build_object('ok',false,'error','NOT_ACCEPTED'); end if;
 if now_kst < r.work_start-interval '60 minutes' then return json_build_object('ok',false,'error','TOO_EARLY'); end if;
 if now_kst >= r.work_end then return json_build_object('ok',false,'error','SHIFT_ENDED'); end if;
 perform pg_advisory_xact_lock(hashtext('punch_emp_'||p_employee::text));
 with latest as(
  select distinct on(event_id) event_id,action,new_event_type,new_event_at,created_by
  from event_corrections where event_id is not null and employee_id=p_employee order by event_id,created_at desc,id desc
 ),eff as(
  select e.id::numeric ord,
   case when l.action='EDIT_TYPE' and l.new_event_type is not null then l.new_event_type else e.event_type end typ,
   case when l.action='EDIT_TIME' and l.new_event_at is not null then
     case when coalesce(l.created_by,'')='system:auto-close' or coalesce(l.created_by,'') like 'substitution:%' then l.new_event_at+interval '9 hours' else l.new_event_at end
   else e.event_at+interval '9 hours' end at_kst
  from attendance_events e left join latest l on l.event_id=e.id
  where e.employee_id=p_employee and coalesce(l.action,'')<>'VOID'
  union all
  select 1000000000000000::numeric+c.id,c.new_event_type,
   case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end
  from event_corrections c where c.employee_id=p_employee and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null
 )
 select typ into last_type from eff where at_kst is not null order by at_kst desc,ord desc limit 1;
 if last_type='IN' then return json_build_object('ok',false,'error','ALREADY_WORKING'); end if;
 insert into attendance_events(employee_id,event_type,event_at,server_received_at,device_id) values(p_employee,'IN',now_utc,now_utc,'SUBSTITUTE:'||p_request);
 update substitution_requests set status='IN_PROGRESS' where id=p_request;
 return json_build_object('ok',true,'type','IN','at',to_char(now_kst,'YYYY-MM-DD"T"HH24:MI:SS'));
end $function$

CREATE OR REPLACE FUNCTION public.substitution_enforce_due()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  n integer:=0;
  now_kst timestamp:=clock_timestamp() at time zone 'Asia/Seoul';
  planned integer;
  in_utc timestamp;
  out_utc timestamp;
  in_kst timestamp;
  out_kst timestamp;
  mins integer;
begin
  for r in
    select * from substitution_requests
    where status in('ACCEPTED','IN_PROGRESS') and work_end<=now_kst
    for update
  loop
    planned:=greatest(1,(extract(epoch from(r.work_end-r.work_start))/60)::integer);
    if r.status='ACCEPTED' then
      update substitution_requests set status='FAILED',actual_minutes=0,resolved_at=now() where id=r.id;
      n:=n+1;
      continue;
    end if;

    in_utc:=null; out_utc:=null; in_kst:=null; out_kst:=null; mins:=0;
    select event_at into in_utc
    from attendance_events
    where employee_id=r.substitute_employee_id and event_type='IN'
      and device_id='SUBSTITUTE:'||r.id::text
    order by id desc limit 1;

    if in_utc is null then
      update substitution_requests set status='FAILED',actual_minutes=0,resolved_at=now() where id=r.id;
      n:=n+1;
      continue;
    end if;
    in_kst:=in_utc+interval '9 hours';

    with latest_corr as (
      select distinct on(event_id) event_id,action,new_event_at,new_event_type
      from event_corrections
      where event_id is not null and employee_id=r.substitute_employee_id
      order by event_id,created_at desc,id desc
    ), eff as (
      select e.id::numeric ord,
             case when c.action='EDIT_TYPE' and c.new_event_type is not null then c.new_event_type else e.event_type end typ,
             case when c.action='EDIT_TIME' and c.new_event_at is not null then c.new_event_at else e.event_at end at
      from attendance_events e left join latest_corr c on c.event_id=e.id
      where e.employee_id=r.substitute_employee_id and coalesce(c.action,'')<>'VOID'
      union all
      select (1000000000000000::numeric+c.id),c.new_event_type,c.new_event_at
      from event_corrections c
      where c.employee_id=r.substitute_employee_id and c.action='ADD'
        and c.new_event_at is not null and c.new_event_type is not null
    )
    select at into out_utc from eff
    where typ='OUT' and at>in_utc
    order by at,ord limit 1;

    if out_utc is null then
      if not exists(
        select 1 from event_corrections
        where employee_id=r.substitute_employee_id and action='ADD'
          and reason='SYSTEM_SUBSTITUTE_END' and created_by='substitution:'||r.id::text
      ) then
        insert into event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
        values(null,r.substitute_employee_id,'ADD',r.work_end-interval '9 hours','OUT',
               'SYSTEM_SUBSTITUTE_END','substitution:'||r.id::text);
      end if;
      out_kst:=r.work_end;
    else
      out_kst:=out_utc+interval '9 hours';
    end if;

    mins:=greatest(0,(extract(epoch from(least(out_kst,r.work_end)-greatest(in_kst,r.work_start)))/60)::integer);
    update substitution_requests
    set status=case when mins>=planned then 'COMPLETED' else 'PARTIAL' end,
        actual_minutes=mins,resolved_at=now()
    where id=r.id;
    n:=n+1;
  end loop;
  return json_build_object('ok',true,'checked',n);
end;
$function$

CREATE OR REPLACE FUNCTION public.substitution_refresh_one(p_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r substitution_requests%rowtype;in_utc timestamp;out_kst timestamp;in_kst timestamp;mins integer:=0;now_kst timestamp:=clock_timestamp() at time zone 'Asia/Seoul';planned integer;
begin
 select * into r from substitution_requests where id=p_id for update;
 if not found or r.status not in('ACCEPTED','IN_PROGRESS','COMPLETED','PARTIAL','FAILED') then return; end if;
 select event_at into in_utc from attendance_events where employee_id=r.substitute_employee_id and event_type='IN' and device_id='SUBSTITUTE:'||r.id::text order by id desc limit 1;
 if in_utc is not null then
  in_kst:=in_utc+interval '9 hours';
  with latest as(
   select distinct on(event_id) event_id,action,new_event_type,new_event_at,created_by
   from event_corrections where event_id is not null and employee_id=r.substitute_employee_id order by event_id,created_at desc,id desc
  ),eff as(
   select e.id::numeric ord,
    case when l.action='EDIT_TYPE' and l.new_event_type is not null then l.new_event_type else e.event_type end typ,
    case when l.action='EDIT_TIME' and l.new_event_at is not null then
      case when coalesce(l.created_by,'')='system:auto-close' or coalesce(l.created_by,'') like 'substitution:%' then l.new_event_at+interval '9 hours' else l.new_event_at end
    else e.event_at+interval '9 hours' end at_kst
   from attendance_events e left join latest l on l.event_id=e.id
   where e.employee_id=r.substitute_employee_id and coalesce(l.action,'')<>'VOID'
   union all
   select 1000000000000000::numeric+c.id,c.new_event_type,
    case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end
   from event_corrections c where c.employee_id=r.substitute_employee_id and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null
  )
  select at_kst into out_kst from eff where typ='OUT' and at_kst>in_kst order by at_kst,ord limit 1;
 end if;
 planned:=greatest(1,(extract(epoch from(r.work_end-r.work_start))/60)::integer);
 if in_kst is not null and out_kst is not null then mins:=greatest(0,(extract(epoch from(least(out_kst,r.work_end)-greatest(in_kst,r.work_start)))/60)::integer); end if;
 if now_kst<r.work_end then
  update substitution_requests set actual_minutes=mins,status=case when in_kst is not null and out_kst is null then 'IN_PROGRESS' when in_kst is not null and out_kst is not null then 'PARTIAL' else 'ACCEPTED' end where id=r.id;
 else
  update substitution_requests set actual_minutes=case when status='COMPLETED' then greatest(actual_minutes,planned) else mins end,status=case when status='COMPLETED' then 'COMPLETED' when in_kst is null then 'FAILED' when mins>=planned then 'COMPLETED' else 'PARTIAL' end,resolved_at=coalesce(resolved_at,now()) where id=r.id;
 end if;
end $function$

CREATE OR REPLACE FUNCTION public.substitution_request_list(p_employee bigint, p_pin text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare h text;q record;
begin
  select pin_bcrypt into h from employees where id=p_employee and is_active=true;
  if h is null or crypt(p_pin,h)<>h then return json_build_object('ok',false,'error','BAD_PIN'); end if;

  perform substitution_enforce_due();
  for q in select id from substitution_requests
    where p_employee in(requester_employee_id,substitute_employee_id)
      and status in('ACCEPTED','IN_PROGRESS')
  loop
    perform substitution_refresh_one(q.id);
  end loop;

  return json_build_object('ok',true,'requests',(
    select coalesce(json_agg(x order by x.work_start desc),'[]'::json)
    from (
      select r.id,r.requester_employee_id,r.substitute_employee_id,a.name requester_name,b.name substitute_name,
             r.work_start,r.work_end,r.status,r.requested_at,r.accepted_at,r.resolved_at,r.note,r.actual_minutes
      from substitution_requests r
      join employees a on a.id=r.requester_employee_id
      join employees b on b.id=r.substitute_employee_id
      where p_employee in(r.requester_employee_id,r.substitute_employee_id)
    ) x
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.system_enforce_store_close(p_store_id bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s public.store_settings%rowtype; now_kst timestamp without time zone:=now() at time zone 'Asia/Seoul'; active_from_kst timestamp without time zone; r record; v_business_date date; v_cutoff timestamp without time zone; v_closed integer:=0;
begin
 if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 select * into s from public.store_settings where store_id=p_store_id order by id desc limit 1;
 if not found then return json_build_object('ok',false,'error','STORE_SETTINGS_MISSING'); end if;
 active_from_kst:=s.auto_close_from at time zone 'Asia/Seoul';
 for r in
  with latest_corr as (
   select distinct on(c.event_id) c.event_id,c.action,c.new_event_at,c.new_event_type,c.created_by
   from public.event_corrections c join public.employees ce on ce.id=c.employee_id
   where c.event_id is not null and ce.store_id=p_store_id order by c.event_id,c.created_at desc,c.id desc
  ),eff as (
   select e.employee_id,case when c.action='EDIT_TYPE' and c.new_event_type is not null then c.new_event_type else e.event_type end event_type,
    case when c.action='EDIT_TIME' and c.new_event_at is not null then case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end else e.event_at+interval '9 hours' end event_at_kst,e.id::numeric ord
   from public.attendance_events e join public.employees ee on ee.id=e.employee_id left join latest_corr c on c.event_id=e.id
   where ee.store_id=p_store_id and coalesce(c.action,'')<>'VOID'
   union all
   select c.employee_id,c.new_event_type,case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end,1000000000000000::numeric+c.id
   from public.event_corrections c join public.employees ee on ee.id=c.employee_id
   where ee.store_id=p_store_id and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null
  ),last_eff as (
   select distinct on(employee_id) employee_id,event_type,event_at_kst from eff where event_at_kst is not null order by employee_id,event_at_kst desc,ord desc
  ) select * from last_eff where event_type='IN'
 loop
  v_business_date:=r.event_at_kst::date-case when (extract(hour from r.event_at_kst)::int*60+extract(minute from r.event_at_kst)::int)<s.open_minute then 1 else 0 end;
  v_cutoff:=v_business_date::timestamp+interval '26 hours';
  if v_cutoff>=active_from_kst and now_kst>=v_cutoff and v_cutoff>=r.event_at_kst then
   if not exists(select 1 from public.event_corrections where employee_id=r.employee_id and action='ADD' and reason='SYSTEM_STORE_CLOSE' and created_by='system:auto-close' and new_event_at=v_cutoff-interval '9 hours') then
    insert into public.event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by) values(null,r.employee_id,'ADD',v_cutoff-interval '9 hours','OUT','SYSTEM_STORE_CLOSE','system:auto-close');v_closed:=v_closed+1;
   end if;
  end if;
 end loop;
 return json_build_object('ok',true,'closed',v_closed,'store_id',p_store_id,'checked_at',now_kst,'active_from',active_from_kst,'hard_stop_minute',1560);
end $function$
